   async Task Initialize(){try{var s=await settingsService.GetAsync(CancellationToken.None);liveBeautySettings=await beautySettingsService.GetAsync(CancellationToken.None)??new BeautySettings();if(s!=null){photoCount=s.PhotoCount;countdown=s.CountdownSeconds;gifDuration=Math.Max(0.4,Math.Min(1.0,s.GifFrameDurationMilliseconds/1000d));waitingTimeout=ToWaitingTimeoutLabel(s.WaitingTimeoutSeconds);autoFlip=s.AutoFlip;imageRotation=s.ImageRotationDegrees;usePortraitCustomer=s.CustomerLayoutMode==CustomerLayoutMode.Portrait;saveLocation=ToSaveLocationLabel(s.SaveLocation);Raise(nameof(PhotoCount));Raise(nameof(Countdown));Raise(nameof(GifDuration));Raise(nameof(WaitingTimeout));Raise(nameof(AutoFlip));Raise(nameof(LiveViewScaleX));Raise(nameof(ImageRotation));Raise(nameof(LiveViewRotation));Raise(nameof(IsQuarterTurn));Raise(nameof(LiveViewCanvasWidth));Raise(nameof(LiveViewCanvasHeight));Raise(nameof(UsePortraitCustomer));Raise(nameof(SaveLocation));}await sessions.GetBaseAsync(CancellationToken.None);var defaultSession=await sessions.GetDefaultAsync(CancellationToken.None);await RefreshSessions(defaultSession.Id);if(!priority.IsCustomerActive)StartScanning();else{IsCameraControlsEnabled=false;ConnectionStatus="Customer application owns camera";}}catch(Exception e){Friendly(e,"Initialization failed");}}
  void StartScanning(){StopScanning();cameraActivated=false;ConnectionStatus="Scanning...";scanCts=CancellationTokenSource.CreateLinkedTokenSource(adminWorkCts.Token);_ = ScanLoop(scanCts.Token);Raise(nameof(ConnectionActionText));CommandManager.InvalidateRequerySuggested();}
  void StopScanning(){var cts=scanCts;scanCts=null;if(cts!=null){cts.Cancel();cts.Dispose();}}
  async Task ScanLoop(CancellationToken token){while(!token.IsCancellationRequested&&!cameraActivated){try{await RefreshCameras();await Task.Delay(1000,token);}catch(OperationCanceledException){break;}catch(Exception e){log.LogDebug(e,"Passive camera scan failed");try{await Task.Delay(1000,token);}catch(OperationCanceledException){break;}}}}
  async Task RefreshCameras(){var values=cameraActivated?await cameras.GetCamerasAsync(CancellationToken.None):await cameras.ScanAsync(CancellationToken.None);var dispatcher=System.Windows.Application.Current?.Dispatcher;if(dispatcher!=null&&!dispatcher.CheckAccess()){await dispatcher.InvokeAsync(()=>ApplyCameras(values));return;}ApplyCameras(values);}
  void ApplyCameras(IReadOnlyList<CameraInfo> values){var selectedId=SelectedCamera?.Id;Cameras.Clear();foreach(var x in values)Cameras.Add(x);SelectedCamera=Cameras.FirstOrDefault(x=>x.Id==selectedId)??Cameras.FirstOrDefault();}
  async Task HandleCameraChange(){await cameraChangeGate.WaitAsync();try{if(customerModeActive)return;var token=adminWorkCts.Token;await RefreshCameras();token.ThrowIfCancellationRequested();if(!cameraActivated)return;if(SelectedCamera==null||!SelectedCamera.IsConnected){cameraActivated=false;await StopLive();ConnectionStatus="Disconnected";CommandManager.InvalidateRequerySuggested();return;}await EnsureLiveViewAsync();await TryLoadProperties(token);}catch(OperationCanceledException){}catch(Exception e){log.LogWarning(e,"Camera state refresh failed");}finally{cameraChangeGate.Release();}}
  async Task Connect(CancellationToken token=default){if(SelectedCamera==null)return;if(customerModeActive||priority.IsCustomerActive){IsCameraControlsEnabled=false;ConnectionStatus="Customer application owns camera";return;}await connectGate.WaitAsync(token);try{if(SelectedCamera==null||customerModeActive||priority.IsCustomerActive)return;var requestedId=SelectedCamera.Id;var cts=CancellationTokenSource.CreateLinkedTokenSource(token,adminWorkCts.Token);connectCts=cts;try{ConnectionStatus="Connecting…";await cameras.ConnectAsync(requestedId,cts.Token);if(customerModeActive)return;var connected=await cameras.GetCamerasAsync(cts.Token);ApplyCameras(connected);SelectedCamera=Cameras.FirstOrDefault(x=>x.IsConnected);if(SelectedCamera==null){cameraActivated=false;ConnectionStatus="Disconnected";return;}cameraActivated=true;StopScanning();ConnectionStatus="Connected";CommandManager.InvalidateRequerySuggested();if(!string.IsNullOrWhiteSpace(WorkingFolder))StorageInfo(WorkingFolder);await EnsureLiveViewAsync();await TryLoadProperties(cts.Token);}catch(OperationCanceledException){if(!customerModeActive){cameraActivated=false;ConnectionStatus="Disconnected";}}catch(Exception e){if(!customerModeActive){cameraActivated=false;ConnectionStatus="Disconnected";log.LogError(e,"Unable to connect camera");}}finally{if(ReferenceEquals(connectCts,cts))connectCts=null;cts.Dispose();}}finally{connectGate.Release();}}
  async Task Disconnect(){CancelConnect();StopScanning();await connectGate.WaitAsync();try{var old=SelectedCamera;try{await recovery.StopAsync(CancellationToken.None);await StopLive(old,true);await cameras.DisconnectAsync(CancellationToken.None);}catch(Exception e){Friendly(e,"Unable to disconnect camera");}finally{cameraActivated=false;ResetCameraUiState();StartScanning();}}finally{connectGate.Release();}}
