  Task CancelSession(){if(draftSession==null)return Task.CompletedTask;draftSession=null;if(activeSession!=null){SessionName=activeSession.SessionName;SessionLocation=activeSession.OutputDirectory;CurrentSession=activeSession.SessionName;WorkingFolder=activeSession.OutputDirectory;StorageInfo(activeSession.OutputDirectory);}Raise(nameof(IsSessionDraft));Raise(nameof(SessionActionText));CommandManager.InvalidateRequerySuggested();LastCapture="Session draft cancelled.";return Task.CompletedTask;}
  async Task SetDefaultSession(){if(SelectedSession==null)return;try{await sessions.SetDefaultAsync(SelectedSession.Id,CancellationToken.None);await RefreshSessions(SelectedSession.Id);LastCapture="Default session: "+SelectedSession.SessionName;}catch(Exception e){Friendly(e,"Unable to set default session");}}
  async Task Capture(){if(!cameraActivated||SelectedCamera==null)return;try{if(activeSession==null)activeSession=await sessions.GetDefaultAsync(CancellationToken.None);CurrentFps=0;activeSession=await capturePipeline.ExecuteAsync(activeSession.Id,SelectedCamera.Id,null,false,CancellationToken.None);var imageId=activeSession.CapturedImageIds.LastOrDefault();LastCapture=imageId+" · "+Path.GetFileName(activeSession.CapturedFiles.LastOrDefault());log.LogInformation("Test capture: {Result}",LastCapture);}catch(Exception e){Friendly(e,"Test capture failed");}}
  async Task EnsureLiveViewAsync(){var camera=SelectedCamera;if(camera==null||!camera.IsConnected){await StopLive();return;}await liveGate.WaitAsync();try{if(liveToken!=null&&string.Equals(liveCameraId,camera.Id,StringComparison.Ordinal))return;await StopLiveCore(null,false);liveBeautySettings=await beautySettingsService.GetAsync(CancellationToken.None)??new BeautySettings();liveBeautyFailed=false;liveBeauty.Reset();for(var attempt=0;attempt<3;attempt++){CancellationTokenSource cts=null;try{cts=new CancellationTokenSource();await live.StartAsync(camera.Id,cts.Token);liveToken=cts;liveCameraId=camera.Id;liveLoopTask=LiveLoop(camera.Id,cts.Token);ConnectionStatus="Connected";return;}catch(Exception e){cts?.Cancel();cts?.Dispose();log.LogWarning(e,"Live View start failed (attempt {Attempt}/3)",attempt+1);try{await Task.Delay(1000);}catch{}}}}finally{liveGate.Release();}}
  async Task StopLive(){await StopLive(SelectedCamera,false);}
  async Task StopLive(CameraInfo camera,bool force){await liveGate.WaitAsync();try{await StopLiveCore(camera,force);}finally{liveGate.Release();}}
  async Task StopLiveCore(CameraInfo camera,bool force){var token=liveToken;var loop=liveLoopTask;var cameraId=liveCameraId??camera?.Id;var hadLiveSession=token!=null;liveToken=null;liveLoopTask=null;liveCameraId=null;if(token!=null)token.Cancel();if(loop!=null)try{await loop;}catch(OperationCanceledException){}catch(Exception e){log.LogDebug(e,"Live View loop stopped with an error");}liveBeauty.Reset();if((hadLiveSession||force)&&!string.IsNullOrWhiteSpace(cameraId))try{await live.StopAsync(cameraId,CancellationToken.None);}catch(Exception e){log.LogWarning(e,"Live View stop failed");}token?.Dispose();}
  void ResetCameraUiState(){cameraEpoch++;CameraProperties.Clear();Cameras.Clear();SelectedCamera=null;LiveImage=null;CurrentFps=0;resolutionWidth=0;resolutionHeight=0;Raise(nameof(Resolution));}
  async Task LiveLoop(string id,CancellationToken token){var watch=Stopwatch.StartNew();var count=0;var lastSignature=0;while(!token.IsCancellationRequested){var iteration=Stopwatch.StartNew();try{var frame=await live.GetFrameAsync(id,token);if(frame?.ImageData!=null){var signature=FrameSignature(frame.ImageData);if(signature!=lastSignature){lastSignature=signature;var displayed=frame.ImageData;if(!liveBeautyFailed&&liveBeautySettings.HasEffect)try{displayed=await liveBeauty.ProcessAsync(frame.ImageData,liveBeautySettings,token)??frame.ImageData;}catch(OperationCanceledException)when(token.IsCancellationRequested){throw;}catch(Exception error){liveBeautyFailed=true;log.LogWarning(error,"Admin Live Beauty failed; raw Live View remains active");}LiveImage=displayed;resolutionWidth=frame.Width;resolutionHeight=frame.Height;Raise(nameof(Resolution));count++;}}if(watch.ElapsedMilliseconds>=1000){CurrentFps=count;count=0;watch.Restart();}var remaining=LiveFrameInterval-iteration.Elapsed;if(remaining>TimeSpan.Zero)await Task.Delay(remaining,token);}catch(OperationCanceledException){break;}catch(Exception e){CurrentFps=0;log.LogWarning(e,"Live View unavailable; retrying");try{await Task.Delay(500,token);}catch(OperationCanceledException){break;}}}}
