   public Task PersistSettingsAsync()=>SaveSettings();
   async Task SaveSettings(){await settingsSaveGate.WaitAsync();try{var s=await settingsService.GetAsync(CancellationToken.None)??new Settings();s.PhotoCount=PhotoCount;s.CountdownSeconds=Countdown;s.GifFrameDurationMilliseconds=(int)Math.Round(GifDuration*1000);s.WaitingTimeoutSeconds=ToWaitingTimeoutSeconds(WaitingTimeout);s.AutoFlip=AutoFlip;s.ImageRotationDegrees=ImageRotation;s.CustomerLayoutMode=UsePortraitCustomer?CustomerLayoutMode.Portrait:CustomerLayoutMode.Landscape;s.SaveLocation=ToSaveLocationMode(SaveLocation);await settingsService.SaveAsync(s,CancellationToken.None);}catch(Exception e){Friendly(e,"Settings could not be saved");}finally{settingsSaveGate.Release();}}
  async Task MonitorCustomerPriority(){var owned=false;while(true){try{var active=priority.IsCustomerActive;if(active&&!owned){owned=true;IsCameraControlsEnabled=false;if(!customerModeActive)await Disconnect();ConnectionStatus="Customer application owns camera";}else if(!active&&owned){owned=false;if(!customerModeActive){IsCameraControlsEnabled=true;ConnectionStatus="Ready to connect";}}await Task.Delay(500);}catch(Exception e){log.LogWarning(e,"Camera priority monitor failed");await Task.Delay(1000);}}}
   void StorageInfo(string path){try{var root=Path.GetPathRoot(path);var drive=new DriveInfo(root);Storage=Math.Round(drive.AvailableFreeSpace/1073741824d,1)+" GB free";}catch{Storage="Unknown";}}
