 public sealed class CameraPropertyRow:ObservableObject { readonly Func<string,Task> changed; string selected; public CameraPropertyRow(CameraProperty model,Func<string,Task> changed){Kind=model.Kind;Values=model.AllowedValues??new string[0];selected=model.Value;IsDisplayOnly=model.Kind==CameraPropertyKind.CameraMode;IsEnabled=model.IsAvailable&&!model.IsReadOnly&&!IsDisplayOnly;this.changed=changed;} public CameraPropertyKind Kind{get;} public string Label=>Kind==CameraPropertyKind.CameraMode?"Camera Mode":Kind==CameraPropertyKind.ShutterSpeed?"Shutter Speed":Kind==CameraPropertyKind.WhiteBalance?"White Balance":Kind==CameraPropertyKind.FocusMode?"Focus Mode":Kind==CameraPropertyKind.MeteringMode?"Metering Mode":Kind==CameraPropertyKind.ExposureCompensation?"Exposure Compensation":Kind.ToString(); public IReadOnlyList<string> Values{get;} public bool IsDisplayOnly{get;} public bool IsEnabled{get;} public string SelectedValue{get=>selected;set{if(IsEnabled&&Set(ref selected,value)&&value!=null)_=changed(value);}} }
